CREATE TABLE `cd_device` (
  `device_id` bigint NOT NULL AUTO_INCREMENT COMMENT '设备ID',
  `device_no` varchar(64) NOT NULL COMMENT '设备编号',
  `device_name` varchar(100) DEFAULT '' COMMENT '设备名称',
  `device_type` char(1) DEFAULT '1' COMMENT '设备类型(1智能手表 2血压计 3血氧仪 4血糖仪)',
  `vendor` varchar(50) DEFAULT '' COMMENT '厂商',
  `model` varchar(50) DEFAULT '' COMMENT '型号',
  `patient_id` bigint DEFAULT NULL COMMENT '绑定患者ID',
  `patient_name` varchar(50) DEFAULT '' COMMENT '绑定患者姓名',
  `online_status` char(1) DEFAULT '0' COMMENT '在线状态(0离线 1在线)',
  `battery` int DEFAULT '100' COMMENT '电量',
  `last_online` datetime DEFAULT NULL COMMENT '最后在线时间',
  `status` char(1) DEFAULT '0' COMMENT '状态(0正常 1停用)',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  PRIMARY KEY (`device_id`),
  UNIQUE KEY `uk_device_no` (`device_no`),
  KEY `idx_patient` (`patient_id`)
) ENGINE=InnoDB AUTO_INCREMENT=9 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='设备档案表';
