--
-- Table structure for table `cd_health_score`
--

DROP TABLE IF EXISTS `cd_health_score`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `cd_health_score` (
  `score_id` bigint NOT NULL AUTO_INCREMENT COMMENT '评分ID',
  `patient_id` bigint NOT NULL COMMENT '患者ID',
  `total_score` int DEFAULT '0' COMMENT '加权风险评分',
  `risk_level` char(1) DEFAULT '1' COMMENT '风险等级(1低危 2中危 3高危)',
  `detail_json` text COMMENT '各指标评分明细(JSON)',
  `trigger_type` char(1) DEFAULT '3' COMMENT '触发来源(1监测 2干预 3定时)',
  `calc_time` datetime DEFAULT NULL COMMENT '计算时间',
  PRIMARY KEY (`score_id`),
  KEY `idx_patient_time` (`patient_id`,`calc_time`)
) ENGINE=InnoDB AUTO_INCREMENT=86 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='健康评分记录表';
/*!40101 SET character_set_client = @saved_cs_client */;

